\caption{\textsf{Iterative-}$\mathsf{Constrained\text{-}Regression}${} (from 3.3)}
        \begin{algorithmic}[1]
        \Procedure{\rm \textsf{Iterative-}$\mathsf{Constrained\text{-}Regression}${}}{$\varepsilon,\delta,\sigma,q,\alpha,k$}
            \vspace{2mm}
            \State {If $\varepsilon \geq \alpha$, set $\varepsilon=\nicefrac{\alpha}{6}$}
            \State Set the accuracy parameters {$\zeta=O((\sigma\varepsilon)^{5q^2}\alpha^{8q})$} and $\gamma=\sigma^{-1}\varepsilon^{-q}$
            \State Set the number of iterations as $T=\nicefrac{1}{\gamma}$
            \vspace{2mm}
            \vspace{2mm}
            \For{$1\leq i\leq T$}
                \State Define the survival set $S_i=H_1\cap H_2\cap\dots H_{i-1}$ if $i>1$ and, otherwise, $S_i=\mathbb{R}^d$
                \vspace{3mm}
                \item[] \phantom{.}\qquad~~ \textit{\#~~Step 1 (Ensure Low-Degree Approximation Exists)}
                \State Obtain $m=\widetilde{O}((\nicefrac{1}{\gamma^3}) \cdot (d^k+\log{\nicefrac{1}{\delta}}))$ samples $U$ from $\euscr{D}$ and $P$ from $\euscr{P}^\star$
                \If{$i > 1$ and either $\left| U\cap S_i \right|\leq \gamma \left| U \right|$ or $\left| P\cap S_i \right|\leq (\nicefrac{\alpha}{2})\left| P \right|$}
                    \State Break out of the for-loop
                \EndIf{}
                \vspace{3mm}
                \item[] \phantom{.}\qquad~~ \textit{\#~~Step 2 (Update Sample Distributions)}
                \State Define $\euscr{D}_i,\euscr{P}^\star_i,\euscr{D}^\star_i$ as the truncations of $\euscr{D},\euscr{P}^\star,\euscr{D}^\star$ to $S$
                \State Construct sampling oracles for $\euscr{D}_i$ and $\euscr{P}^\star_i$ via rejection sampling from $\euscr{D}$ and $\euscr{P}^\star$
                \vspace{3mm}
                \item[] \phantom{.}\qquad~~ \textit{\#~~Step 3 (Solve $i$-th Pessimistic-ERM{} Instance)}
                \State $H_i~\longleftarrow$~\hyperref[alg:constReg]{{\rm \textsf{Boosted-}}$\mathsf{Constrained\text{-}Regression}${}}($\zeta,\delta,\sigma,q,k$) with
                sample access to $\euscr{D}_i$ and $\euscr{P}^\star_i$
                \item[] \phantom{.}\qquad~~ \textit{\#~~Here, \hyperref[alg:constReg]{{\rm \textsf{Boosted-}}$\mathsf{Constrained\text{-}Regression}${}} is the algorithm referenced in 4.3}
            \EndFor{}
            \vspace{2mm}
            \State \textbf{return} $H\coloneqq H_1\cap H_2\cap\dots\cap H_\ell$ where $\ell$ is the last iteration of the for-loop completed
        \EndProcedure
        \end{algorithmic}

Let 1, 2 hold.
            Fix any $\varepsilon,\delta\in (0,\nicefrac{1}{2})$ and $k$ such that degree-$k$ polynomials $\zeta$-approximate $\mathdutchcal{H}$ with respect to $\euscr{D}$ in $L_1$-norm for $\zeta\leq O(\alpha^{8q})\cdot (\sigma\varepsilon\alpha)^{5q^2}$.
            Then, there is an algorithm (alg:main) that, given 
                any $\varepsilon,\delta\in (0,1)$, 
                the constants $\sigma,q$ from 1,and 
                $n=\mathrm{poly}(d^k,\nicefrac{1}{\zeta},\log{\nicefrac{1}{\delta}})$ samples from each stream in PIU Learning model (1), 
            outputs a hypothesis ${h}\colon \euscr{X}\to\ensuremath{\left\{0, 1\right\}}$ such that, with probability $1-\delta$, 
            \[
                \Pr_{\euscr{D}^\star}\left({h}(x)\neq h^\star(x)\right)\leq \varepsilon\,.
            \]
            The algorithm runs in time $\mathrm{poly}(n)$.

\caption{\textsf{Boosted-}$\mathsf{Constrained\text{-}Regression}${}}
        \begin{algorithmic}[1]
        \Procedure{{\rm \textsf{Boosted-}}$\mathsf{Constrained\text{-}Regression}${}}{$\zeta,\delta,\sigma,q,\alpha,k$}
            \State Initialize variable $i=1$

            \vspace{2mm}

            \State\textit{\#~~Subroutine A (Obtain Samples)}
                \State Obtain sets $P$ and $U$ of $\widetilde{\Omega}\left(
                    \left(\nicefrac{1}{\zeta^2}\right)\cdot
                        \left(d^k+\log{\nicefrac{1}{\delta}}\right)
                \right)$ positive and unlabeled samples  
                \item[]\quad~ respectively from the PIU learning model (1) 
                \vspace{4mm}
            \State \textit{\#~~Subroutine B (Solve Constrained Regression)}
            \State Find the optimal solution $p_i(\cdot)$ of the following program for $\rho=\frac{2}{\alpha\sigma} \cdot \zeta^{1/(2q)}$  
            Constrained Regression) \ (#1
            \[
                \min_{{\rm deg}(p)\leq k} \frac{\sum_{x\in U} \left| {p(x)} \right|}{\left| U \right|}
                \,,~~
                \text{s.t.}\,,~~
                \frac{\sum_{x\in P} \min\left\{p(x), 1\right\}}{\left| P \right|}     \geq 1  -  \rho
                \,.
                \addtocounter{equation}{1}\tag{\theequation}
            \]
            #1
            \State \textit{\#~~This program can be solved by formulating it as a linear program over monomials of degree at}
            \State \textit{\#~~most $k$ and using any polynomial-time linear program solver (see E.3 for details)}
            \State Let $H_i=\mathds{1}\{p_i(\cdot)\geq t_i\}$ where $0\leq t_i\leq 1-\sqrt{\rho}$ is chosen to minimize $\sum_{x\in U}  \mathds{1}\{p_i(x)\geq t_i\}$  
            \vspace{4mm}
            \State \textit{\#~~Subroutine C (Boost Performance)}
            \State Repeat the Subroutines A and B for $T=O(\left(\nicefrac{1}{\sqrt{\zeta}}\right)\cdot \log{\nicefrac{1}{\delta}})$ times to get $H_1,H_2,\dots,H_T$ 
            \State Select fresh sets $P'$ and $U'$ of $\widetilde{O}(\left(\nicefrac{1}{\zeta}\right)\cdot \log{\nicefrac{1}{\delta}})$ samples from the PIU model (1)
            \State \textbf{return} $H_i$ that minimizes $\left| H_i\cap U' \right|$ among $1\leq i\leq T$ 
        \EndProcedure
        \end{algorithmic}

Suppose 1, 2 hold.
            Fix any $\delta\in (0,\nicefrac{1}{2})$, $k$ such that degree-$k$ polynomials $\zeta$-approximate $\mathdutchcal{H}$ with respect to $\euscr{D}$ in $L_1$-norm for $0<\zeta\leq O({\alpha\sigma}{})^{2q}$, and $n=\mathrm{poly}\left(d^k, \nicefrac{1}{\zeta}, \log{\nicefrac{1}{\delta}}\right)$.
            There exists a polynomial time algorithm (alg:constReg) that given $n$ independent samples from the PIU learning model (1), outputs a degree-$k$ PTF $H$, s.t., the following hold with probability $1-\delta$
            \begin{enumerate}
                \item $\euscr{D}^\star({H^\star} \setminus H)\leq O(\nicefrac{1}{\alpha\sigma}) \cdot \zeta^{{1/(4q)}}$; and 
                \item $\euscr{D}(H)\leq \ensuremath{\mathrm{OPT}}_{\rm PERM} +
                    O(\nicefrac{1}{\alpha\sigma})\cdot {\zeta^{{1/(4q)}}}+O(\delta)$. 
            \end{enumerate}
            \mbox{Where $\ensuremath{\mathrm{OPT}}_{\rm PERM}\coloneqq \min_{H\in \mathdutchcal{H} \,:\, \euscr{P}^\star(H)=1} \euscr{D}(H)$ is the optimal value of Pessimistic-ERM{} with tolerance $\rho=0$.}\footnote{Note that Pessimistic-ERM{} is defined with respect to samples and, hence, is a random variable. $\ensuremath{\mathrm{OPT}}_{\rm PERM}(\rho)$ is the limiting optimal value as the number of samples goes to infinity.}

Suppose 1, 2 hold.
            Fix any $\delta\in (0,\nicefrac{1}{2})$, $k$ such that degree-$k$ polynomials $\zeta$-approximate $\mathdutchcal{H}$ with respect to $\euscr{D}$ in $L_1$-norm for $0<\zeta\leq O({\alpha\sigma}{})^{2q}$, and $n=\mathrm{poly}\left(d^k, \nicefrac{1}{\zeta}, \log{\nicefrac{1}{\delta}}\right)$.
            There exists a polynomial time algorithm (alg:constReg) that given $n$ independent samples from the PIU learning model (1), outputs a degree-$k$ PTF $H$, s.t., the following hold with probability $1-\delta$
            \begin{enumerate}
                \item $\euscr{D}^\star({H^\star} \setminus H)\leq O(\nicefrac{1}{\alpha\sigma}) \cdot \zeta^{{1/(4q)}}$; and 
                \item $\euscr{D}(H)\leq \ensuremath{\mathrm{OPT}}_{\rm PERM} +
                    O(\nicefrac{1}{\alpha\sigma})\cdot {\zeta^{{1/(4q)}}}+O(\delta)$. 
            \end{enumerate}
            \mbox{Where $\ensuremath{\mathrm{OPT}}_{\rm PERM}\coloneqq \min_{H\in \mathdutchcal{H} \,:\, \euscr{P}^\star(H)=1} \euscr{D}(H)$ is the optimal value of Pessimistic-ERM{} with tolerance $\rho=0$.}\footnote{Note that Pessimistic-ERM{} is defined with respect to samples and, hence, is a random variable. $\ensuremath{\mathrm{OPT}}_{\rm PERM}(\rho)$ is the limiting optimal value as the number of samples goes to infinity.}

In each iteration $i$ where the for-loop in alg:main executes, the following hold:
                \begin{enumerate}
                    \item Degree-$k$ polynomials $(\nicefrac{\zeta}{\gamma})$-approximate $\mathdutchcal{H}$ with respect to  $\euscr{D}_i$ in $L_1$-norm. 
                    \item $(\euscr{D}^\star_i,\euscr{P}^\star_i,\euscr{D})$ is a valid PIU learning instance with constants $\sigma'\geq \nicefrac{\alpha^2 \sigma}{3}$ and $q'=q$.
                \end{enumerate}

For each $i$, $H_i$ is feasible for Pessimistic-ERM{} over samples $P_i$ and $U_i$ with tolerance $\rho=
                    \sqrt{\nicefrac{2}{(\alpha\sigma)} }\cdot \zeta^{1/(4q)}
                $.

$\operatornamewithlimits{\mathbb{E}}_{U_i\sim \euscr{D}}\left[
                \left(\nicefrac{1}{\left| U_i \right|}\right)\sum_{x\in U_i} \left| p_i(x) \right|\mid \ensuremath{\mathscr{F}}
            \right] \leq \euscr{D}(H_{\ensuremath{\mathrm{OPT}}}) + \zeta +4\delta.$
